#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (4) ---
patchFile('siman_031/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The laws of piercing the brain and its membranes. In it are 4 seifim. The brain has two membranes, one upon the other. If the lower one was perforated — if the perforation is bore through completely — treifah; but if only the upper one was perforated alone — kosher. {Rama: And some declare treifah also when only the upper membrane was perforated (Bahag, brought by Hagahot Ashiri and Tur HaDeshen siman 166 and Hagahot ShaDaL siman 81) — and such is the custom unless it is not a place of great loss (his own opinion).}`,
  '2#main': `The brain itself — if a little of it decayed or was crushed, and the membrane remains intact — kosher. And if it spilled like water or like wax — treifah. And if water was found inside the membrane, and a corresponding amount is missing from the brain: if the brain surrounds the water on all sides so it was not exposed even to the membrane — kosher; and if not — treifah. And the same law applies if the water was placed inside a small pouch (meaning like a pouch-shape). If the brain surrounded it so it was not exposed even to the membrane — kosher; and if not — treifah. {Rama: And likewise if the pouch was placed between the membrane and the skull — treifah (Hagahot R' Yehuda on chapter Aleph Tav). If there was a doubt whether it was covered by brain or not — treifah. Therefore one must be careful when opening the head to open it in a manner whereby one can see whether the brain surrounds it if water is found there or not. And nevertheless one need not check afterward, for we rely on the majority and may throw away the head or sell it to a non-Jew without opening (his own opinion).}`,
  '3#main': `If a worm was found in the membrane of the brain and the brain remains intact, and there is neither a trace nor a drop of blood in the lower membrane — kosher. And some say we are not expert in examination and declare treifah (and such is the custom). But if it was found outside the cavity — such as in the nostril — kosher, for we presume it never reached the brain.`,
  '4#main': `The bone in which the brain rests has a large cavity like a pot, and at its mouth toward the neck are like two bulbs; and everything of the brain inside the cavity up to the bulbs — and the bulbs themselves — are judged as brain; and its perforation in any amount; and from there onward it is judged as spinal cord.`,
});

// --- siftei-kohen (11) ---
patchFile('siman_031/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#_': `<b>If not in a place of great loss.</b> And from Maharshal's words in chapter Aleph Tav siman 11 it appears that even in a place of great loss one should declare treifah; and so ruled Bach there — see there.`,
  '2#א': `[<b>The brain itself that decayed a little of it, etc.</b> This is the wording of Rambam, and Tur wrote: if a little is missing from the brain, such as if it decayed, etc.; and in my books I proved that all poskim agree in this: even if it decayed or was crushed so that a little is missing — in a case where if the same occurred in the spinal cord one would hold it and leave the empty part above his hand and it would stand and not bend — kosher; but if much is missing so that if the same occurred in the spinal cord, if much protruded above his hand it would bend — treifah. And likewise regarding the spinal cord the law is the same. Therefore Tur wrote in siman 32 seif 4: if a little of the brain is missing and it became hollow — kosher — to exclude if much is missing, for then treifah, since if one placed it in his hand the empty part outside his hand would sag. But when it melted like wax they did not distinguish — neither here nor in siman 32 — between a little and much, because its way is to melt greatly; and the distinction is only whether it was smoothed well or not: when smoothed well like wax then it sags and is treifah, and if not — kosher. And so is the opinion of R' Yerucham, who wrote: "it became mushy" — meaning it became hollow and not so much as "it melted" — kosher — end. And therefore he means: its way is to melt greatly, and if much became hollow too it could not stand and would be treifah; therefore it is not kosher except when a little became hollow and not so much as melted. And this is Rashi's view, who explained on that which the Gemara says "it melted" — treifah because it cannot stand: meaning it melted but not so much that it would pour like a pitcher of water, but rather when one holds it and leaves a little above the hand it bends and falls; and on "it became mushy" — kosher — he explained: a little of the brain became hollow by itself. And so is Rashba's view in Tur HaDeshen the long one (daf 39a). And now — what Rambam and Mechaber wrote, "decayed or was crushed," etc. — means through deficiency, for presumably a little is missing when it decays or is crushed; and as Mechaber wrote in siman 32 explicitly; and as "and the membrane remains intact" implies: wherever the membrane remains, even if the brain itself is deficient through decay — kosher. And all this is clear in my eyes, not like Bach who was lengthy and multiplied dispute among poskim and thought to breach a rampart against Tur — but in my humble opinion, as I wrote, now all poskim are struck with one blow and there is no dispute here — examine well.]`,
  '2#ב': `[<b>And if it spilled like water or like wax — treifah.</b> Meaning in a case parallel to the spinal cord: if one placed it, it would not stand — as below siman 32; so too Tur and Maharshal there siman 14.]`,
  '2#ג': `[<b>And likewise if the pouch, etc.</b> And all the more if water is found between the membrane and the skull — treifah.]`,
  '2#ד': `[<b>Therefore one must be careful, etc.</b> Meaning: if they opened the head before they knew of the defect by chance until a doubt arose whether the brain surrounds the water or the pouch — treifah; and so Ohr Zarua explicitly; and see what I wrote in siman 50 s.k. 3.]`,
  '2#ה': `[<b>And nevertheless one need not check afterward, etc.</b> See Bach here and at the end of siman 101.]`,
  '3#א': `[<b>And treifah.</b> For we are concerned that perhaps before slaughter it separated and perforated the lower membrane; and do not compare to a worm found on the lung below siman 36 seif 5 — kosher because it separated after slaughter, for that case is different since it is treifah only through perforation of both membranes; but below siman 48 it appears we do not distinguish so much in this — see Darkei Moshe. And Darishah answered: that case is different because the reason — as written there — is that while the animal lives a worm cannot perforate through the constant fluttering of the lung without pause; and likewise in the crop, end siman 49: since its membranes are hard and thick we are not concerned it perforated them while alive — unlike the brain membrane — end. And see siman 36 s.k. 17.]`,
  '3#ב': `[<b>And such is the custom, etc.</b> It implies we declare treifah only because we are not expert in examination; and in Hagahot R' Yehuda, who is the source of this law, he wrote: it is not kosher only according to the view that the upper membrane alone perforated is kosher (and that is Mechaber and his supporters); but according to the view that the upper membrane alone is treifah — here too, since the worm was found in the upper membrane of the brain — treifah; and it is simple. And if so, Bach who ruled above that the upper alone perforated is treifah — here too, even if we were expert in examination it would be treifah; only he informs us that the reason we are not expert is that we must be concerned the lower membrane was perforated — forbidden even with great loss. Or alternatively: the reason we are not expert is that even if there is no trace at all in the lower or upper membrane — treifah, as Tur HaDeshen wrote explicitly and Darkei Moshe brings; however Maharshal's view there siman 11 is to permit if no trace is found in the upper or lower.]`,
  '4#א': `[<b>And the bulbs are included.</b> Rashi explained: brain opposite the bulbs.]`,
  '4#ב': `[<b>And its perforation in any amount.</b> Meaning: perforation of its membrane in any amount.]`,
  '4#ג': `[<b>It is judged as spinal cord.</b> And perforation of its membrane in the majority — as below in the siman that follows.]`,
});

// --- turei-zahav (4) ---
patchFile('siman_031/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Unless in a place of great loss.</b> Maharshal and Maharach prohibit even in a place of great loss, for it is a safek d'oraisa; and especially since Bahag is among those who forbid.`,
  '2#_': `<b>And missing from the brain, etc.</b> But if the brain is whole on all its sides and after the head was cut and the brain removed a little water is found in the skull — there is no prohibition here; for the essence of the prohibition in water is that we say the brain melted and became water; but here we see the brain is whole — there is no prohibition, and the water came from elsewhere. But in water inside the pouch that lies between brain and membrane, or between membrane and skull — even if the brain is whole — treifah, for we see it came from the brain — as above.`,
  '3#_': `<b>To throw away the head, etc.</b> It is simple this refers to a place where no defect appears before us; but if there is a defect — meaning the animal while alive was shaking its head, called in foreign tongue "schwindel" — it is obvious one must forbid until permissibility is clarified by opening its head; and so Maharach.`,
  '4#_': `<b>For we presume it did not reach, etc.</b> And even though the worm's mouth faces outward and it appears it was already on the brain — nevertheless it is permitted because of a double safek: perhaps it turned over and never reached there at all; and if you say it reached — perhaps it did not perforate the membrane so much — see Darkei Moshe. And it is wondrous: from a needle in the body cavity we hold treifah because perhaps one of the places was perforated — see siman 51; and behold there too is a double safek; and in Or Zarua the long one he gave another reason: we do not establish prohibition from place to place. On this too it is difficult: for Beit Yosef wrote in the name of Rashba there that whenever a thorn was inserted not in our presence into the heart — even though it did not perforate a bore-through hole — treifah, lest perhaps one of the other organs was perforated and afterward it was inserted into the heart; behold we establish prohibition from place to place. Therefore in my humble opinion: here they did not permit when found outside the cavity except after examination — they examine the brain membrane and find no defect; and although Shulchan Aruch wrote at the beginning we are not expert — that refers to the cavity itself, not to permit through examination alone; unlike here, where there is another factor for leniency: it was found outside the cavity — we may well rely on examination; but if they did not examine the membrane it appears one must forbid even outside the cavity, lest it was in the cavity and came out — as above. And further one may answer: in a needle in the body cavity you must say it made some hole and entered there — if so, one may well be concerned perhaps one of the organs was perforated; unlike here, where it is not necessary the worm made a hole — therefore we do not establish prohibition from place to place; and so is proven in siman 33 seif 9 as written there. If so, one need not examine the membrane here at all; but nevertheless it appears proper to examine the membrane since clarification is possible — we do not rely on safek (we stand) on the safek.`,
});

// --- baer-heitev (10) ---
patchFile('siman_031/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#_': `<b>Great loss.</b> Maharshal and Bach forbade even with great loss. Peri Chadash wrote: the main thing is to be lenient like Hagahot Maimoniyot.`,
  '2#א': `<b>Kosher.</b> Shach wrote: even through a little deficiency — in a case where if the same occurred in the spinal cord one holds it and leaves the empty part above his hand and it would stand and not bend — kosher; but if much is missing so that if the same occurred in the spinal cord, if much protruded above his hand it would bend — treifah. And specifically in brain adjacent to the membrane; but if it melted in the middle while the brain surrounds all around — kosher (Maharam Alashkar in the name of Peri Chadash).`,
  '2#ב': `<b>Treifah.</b> Meaning: if it were thus in the spinal cord it would not stand — and see above siman 32.`,
  '2#ג': `<b>Treifah.</b> Taz ruled: if the brain is whole on all sides and after removing the brain a little water is found in the skull — kosher; for the essence of prohibition in water is lest it is from the brain that melted; unlike here where we see the brain whole. But in water inside the pouch between brain and membrane or between membrane and skull — even if the brain is whole — treifah, for we see it came from the brain. Shach wrote: all the more if water is found between membrane and skull. Peri Chadash disputes Taz and concludes: if water or pouch is found in the brain itself — whether whole or deficient — the brain must surround the water or pouch, for then it is healthy; and if the water or pouch is exposed to the membrane in any manner — treifah; and if placed between membrane and skull — even if the brain is whole — treifah; and all the more if found between membrane and membrane. (Maharam Alashkar.) (And it appears to me we deal when a little of the brain is missing, per Taz.)`,
  '2#ד': `<b>Opening.</b> Shach wrote: this is specifically where no defect appears before us; but if there is a defect — such as schwindel, shaking its head — forbidden until permissibility is clarified by opening its head — Taz. And now the custom is in the month of Tammuz not to open any head of small animals such as kids and lambs, because water is common in them and one cannot be careful in opening if they are covered; for this we rely on the majority — Beit Yosef. Once a sheep's head came before us and something like saliva issued from the head near the horn; we cut the head and removed the brain; the bone was whole and we declared kosher, for the moisture came only from the root of the horn — as Nahalat Shiva in the name of Maharshal. If water is found in a lamb's head — Damtrafa in it — and it is unknown which lamb: one must check the spinal cords of the sheep; and any sheep in which water is in the brain in the head and water was in the cord proceeding from brain to spinal column — we presume that head is from that sheep to permit the others — Bach, end siman 101; and Taz wrote it is not worthwhile to permit on this safek — see there end siman 101. Jews who bought meat from a non-Jewish butcher before they knew the animal had water in its brain — afterward when they knew, they returned the meat; one did not wish to return, claiming the membrane surrounded it and therefore the meat is kosher. He ruled in responsum Noda B'Yehudah siman 15 they must put him in nidui, since the law is not clear to all and a question to a sage is required — see there.`,
  '3#א': `<b>And treifah.</b> Shach wrote: and it is not comparable to worms found on the lung below siman 36 seif 5, for that case is different: there a worm cannot perforate through the lung's constant fluttering without pause while alive; and likewise in the crop end siman 49: its membranes are hard and thick — we are not concerned it perforated them while alive — unlike the brain membrane.`,
  '3#ב': `<b>And such is the custom.</b> Shach wrote: even with great loss. Maharshal permits if no trace is found in upper or lower.`,
  '3#ג': `<b>Ever.</b> Taz wrote: and even though the worm's mouth faces outward and it appears it was on the brain — permitted, for perhaps it turned over and never reached there; and if you say it was there — perhaps it did not perforate the membrane — a double safek; nevertheless one may not permit except after examination, for it is no better than a needle in the body cavity siman 51, where there is also a double safek; and even though one may distinguish — nevertheless it is proper to examine the membrane since clarification is possible; and here there is another factor for leniency.`,
  '4#א': `<b>Included.</b> Meaning: brain opposite the bulbs.`,
  '4#ב': `<b>Spinal cord.</b> Meaning: and perforation of its membrane in the majority — in animal and bird there are also these two bulbs.`,
});

// --- beer-hagolah (4) ---
patchFile('siman_031/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `The established sugya of Rav and Shmuel and the latter wording and the text of the books before us — Chullin daf 45; Rif; and it appears to Ran that so is Rambam's view in chapter 6 of Hilchot Shechitah.`,
  '2#_': `Ran there on the mishnah and Rashba in his chiddushim.`,
  '3#_': `There they said in the house of Rav regarding the spinal cord; and it appears there the same applies to the brain.`,
  '4#_': `Rif.`,
});

// --- beur-hagra (11) ---
patchFile('siman_031/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `<b>Perforated, etc.</b> Per Rif and Ra'osh text: upper membrane — and "they say" lower membrane; and Rif ruled like the latter wording per his method; and further Rabban Gamliel and R' Yehuda ben Levi reversed to give a sign. (Likut) If the lower was perforated, etc. — per Rif text; but our text is until the lower membrane was perforated; and Tosafot HaRosh agreed for halakhah and proof (for the view that lower membrane requires both) from the sugya there 56 — even though one may reject: there necessarily the lower was not perforated without the upper; and some ruled like the first wording stringently — end.`,
  '1#ב': `<b>And some, etc.</b> Beit Yosef wrote: Bahag explains the first wording holds specifically upper alone; the latter wording holds even lower alone, and all the more upper. And this is according to the sugya there 56 "it works out," etc. But it appears he ruled like both wordings stringently — as Tosafot wrote there s.v. mar, etc.`,
  '2#א': `The brain, etc. — Rambam's wording; and as the Gemara cites Rashba, etc.; and "this became mushy" cannot be explained like by the spinal cord "it swayed," for that is inapplicable here — it must mean decayed; and there "I am not" — etc.; and "this became mushy" means it was crushed, for one cannot say it decayed immediately when slaughtered; and for the law swaying, crushing, and decaying are all one — only Rambam wrote as the Gemara states.`,
  '2#ב': `<b>And if, etc.</b> As Mechaber wrote: melted, etc.; and "like water" means like a full pitcher of water; and there "it melted," etc.; and Rif explained: it melted like wax from fire; and when one places it, etc.; and regarding the brain they said: that one melted — it was stated; if so, all the more for crushed; and also they challenged from brain to spinal cord — learn they are equivalent.`,
  '2#ג': `<b>And if found, etc.; and the same, etc.; and likewise, etc.</b> For whatever is exposed to the membrane does not return healthy and will perforate the membrane; unlike the brain which is not harmed — for all brain disqualifications are because of the membrane — see Rashi s.v. mipnei kevado, etc.; and all these, etc.`,
  '2#ד': `<b>There was a doubt, etc.</b> And we do not say: it was slaughtered — permitted — as written above siman 50 seif 1 in the gloss; and see there.`,
  '2#ה': `<b>And nevertheless one need not, etc.</b> See Rashi 12a s.v. pesach; and on this, etc.; and see Gemara 11a; and we are concerned perhaps, etc.; and even though one rejects: it is mere pushing off (see above siman 39 s.k. 1).`,
  '3#א': `<b>If found, etc.</b> See Bahag and Tosafot there s.v. veniker, etc.; and although they wrote there "and further," etc.; and so in Zevachim 116a in the name of Rabbenu Tam — they already refuted there from Chullin 43a deriving from man to animal; and Bava Kamma 51a challenged him, etc.; and Tosafot there s.v. na'avid, etc.; and Bekhorot 37b s.v. kedei, etc.; and Avodah Zarah 6a s.v. vedilma, etc.; and Chullin 11b s.v. vedilma, etc.; and there 42 s.v. ve'amar, etc.; and so Maggid Mishneh in chapter 13 of Hilchot Gerushin halakhah 16 in the name of Ramban and Rashba: law of from the knee upward (mishnah Yevamot 121a) after twelve months — as Yerushalmi there: R' Chaggai asked before R' Yosa: is it reasonable to give him respite for treifah? He said: I too hold thus — and Avodat HaKodesh siman 17 32b (see Beit Shmuel).`,
  '3#ב': `And no trace in the lower membrane — per Rif's method as in seif 1. Hagahot R' Yehuda and Tur HaDeshen — see there.`,
  '3#ג': `<b>And some say, etc.</b> As written above end siman 30 — see there.`,
  '3#ד': `<b>But if, etc.</b> For we do not establish prohibition from place to place; and we say here: found, etc.; and as written in Orach Chaim siman 467 — see there; and even though its face is outward we presume perhaps it turned over — like a needle in the body cavity there 49a: perhaps they ate, etc.; and further it is a double safek: perhaps it was not there; and if you say it was — perhaps it did not perforate — see first chapter of Ketubot 9a.`,
});

// --- kereti (8) ---
patchFile('siman_031/kereti/part-001.txt', 'kereti', {
  '1#א': `A bore-through perforation — and many authors hold we require both perforated; and if we require them opposite each other — see Peleti, where I placed adjacent to Ra'avan in Ra'osh.`,
  '1#ב': `Bore-through — treifah; see Peleti what I wrote on this. Treifah — see Peleti what I wrote on this.`,
  '2#א': `A little — Shach inferred from the word "a little" that much is treifah; and he gave a measure: we estimate whether so much is missing that in the spinal cord it could not stand — treifah; Peri To'ar agreed; see Peleti: this is incorrect — only "a little" excludes the majority — see there.`,
  '2#ב': `And missing from brain — Taz's view: when we require brain surrounding, it is when something is missing from the brain; but if nothing is missing, brain surrounding is unnecessary; and likewise in melting — if the brain surrounds — kosher; Peri Chadash disputes; see Peleti where I agreed with Taz — his words are reasonable.`,
  '2#ג': `And likewise if found — and all the more water between membrane and skull — treifah — Shach.`,
  '2#ד': `Therefore one must be careful, etc.: if they open and water flows and they do not know whether the brain surrounded — safek issur; and see below siman 56; and one may throw away the head unless an animal with schwindel, where water is more common than lung examination — examination required.`,
  '3#א': `And such — see Peleti: therefore custom is that no membrane was perforated — only through the nostril it entered like Titus; see Peleti one should be stringent and not rely on the act of Titus — see there.`,
  '3#ב': `Custom; and that which we do not say "after slaughter" — the latter authorities were lengthy; see Peleti where I explained we deal when found between membrane and membrane — see there.`,
});

// --- peleti (6) ---
patchFile('siman_031/peleti/part-001.txt', 'peleti', {
  '1#א': `The brain has two membranes, etc.; and many geonim hold we require both upper and lower perforated; Or Zarua wrote for this view: perhaps it resembles the crop — not opposite each other is kosher; Bach disputes; see Peri Chadash s.k. 1. It appears Ra'avan holds like Or Zarua: Ra'avan proved we require both perforated — otherwise what use is inserting the hand and pressing to see if it spurts? Perhaps only the lower was perforated and not the upper — then with lower perforation alone treifah, yet it would not spurt at the upper because the upper was not perforated and seals; and the Ra'osh wondered: the weasel struck the chicken's head from outside — how can the inner hole exist without the outer? An answer is needed, for such a simple matter would not be hidden from Ra'avan's wisdom; but one must say the Gemara said the weasel's teeth are curved. And one who examines by hand certainly does not dispute the reality whether weasel teeth are curved — only he holds one cuts the bone at the weasel's blow and around, and the membrane is exposed — why need "the bone seals"? One cuts the bone and examines the membrane — simple. But it is difficult: perhaps the blow was in a place passing through both membranes not opposite each other; if so, even if it spurts through a hole in the lower membrane, the upper membrane at that place seals — the upper hole is not aligned with the lower. Only what difference in truth if not aligned — kosher, for one protects the other like the crop; but this is as Or Zarua said if we require both perforated; but if the lower alone is perforated — properly difficult: perhaps they perforated not aligned and treifah because of lower membrane perforation, and it cannot spurt because at that place the upper membrane protects and the holes were slanted; and if not aligned — what of it? With lower alone if perforated — treifah; therefore we require both; and since they are not opposite each other — kosher as in the crop; and Or Zarua's law is compelled.`,
  '1#ב': `The lower was perforated bore-through — treifah. One should analyze: we say in the Gemara one inserts his hand inside and checks if it spurts; we rule below siman 33: a thorn sat in the esophagus — we are concerned perhaps the outer skin was perforated and healed in the membrane from the blow; why here with thorn and weasel tooth in the outer membrane do we not concern the inner membrane rose and healed from the blow and there is no hole? Do not say the inner membrane is soft and bursts from pressing — for according to the view that lower membrane alone was perforated we do not say the inner is soft and bursts; otherwise it would be difficult for one who examines by hand — he too causes monetary loss to Israel like one who examines with a nail: from pressing the lower bursts and spurts, and in truth the lower was not perforated; therefore one must say they hold the lower is not soft and does not burst. But even though we say the lower is not soft and does not burst — that is the membrane itself; but what was perforated and is only membrane from a blow — that certainly bursts and is soft — no difficulty. From this the many authorities who ruled upper perforated had proof: why does the Gemara challenge for the view upper alone — even for the view lower too it is difficult: perhaps the membrane rose and sealed? And if you say it is soft and bursts — I had not yet brought this to mind; therefore they hold one may indeed say thus, only the Gemara challenges according to the halakhah we hold: upper alone. Accordingly Ra'avan and Ra'osh followed their method: we are not concerned it healed — no difficulty; no proof here; therefore they ruled both must be perforated — examine well.`,
  '2#א': `Decayed a little, etc. — most authors brought the word "a little" and Shach inferred specifically a little but not more; yet from Tosafot's knowledge — what is called little and what much? Shach gave a sign Peri Chadash agreed: if so much missing that opposite it in the spinal cord it could not stand — treifah; less — kosher; see there he was lengthy in his book which we have not seen. I wonder: if so, what does the Gemara challenge from the baraita "became mushy" — kosher — from this man whose brain became mushy? Presumably there much became hollow? Do not say "mushy" indicates little deficiency — that is only mushy from hollow, as we translate "the dead shall be hollowed" — "became mushy"; and the main difficulty: what difference "melted" and "mushy" for this view? Why distinguish mushy from melted — the mishnah teaches melted treifah and mushy kosher: perforce if it can stand in both — kosher; if cannot stand in both — treifah; what matter little or much — all depends on ability to stand? I also did not understand: melted is quality of the brain causing inability to stand in spinal cord — then we have a kal vachomer: even in brain disqualified since we see deficiency prevents standing. But if inability to stand is because little fell into minority of brain in the cord — that has no comparison to head: missing a quarter of head — shall we say if missing quarter in spinal cord treifah, also in head treifah? Shall we learn one from the other? If missing half-quarter from spinal cord cannot stand, in skull the deficiency is according to brain mass and skull holding. We never found to learn brain deficiency from spinal cord deficiency; Rambam and Or Zarua wrote simply "missing" without "a little"; therefore clear there is no precision on little or much — only Rambam and Or Zarua intend: do not think "became hollow" means majority; that deficiency disqualifies by reason: as if all missing — "a little" excludes majority which certainly treifah — examine well.`,
  '2#ב': `And missing from brain, etc. — Taz and Maharikash: specifically when missing from brain; but if brain whole and water present — not treifah even touching membrane. Peri Chadash attacked: in the end water touches membrane. I did not know place of attack: Bahag and Rabeinu Elyahu came to add treifot Chazal listed — where was this treifah in the Gemara? Water in death touching membrane in Chazal's words — should Chazal have listed it? But clear the essence of treifah in the Gemara is melted and Rashi explained spilled like water; these geonim only came to be lenient per their tradition: specifically touching membrane — then not healthy; but in middle of brain — sometimes a little spills like water and returns healthy; likewise in melting not so much as water; and if not touching membrane — returns healthy — as Peri Chadash s.k. 2. But if brain not missing and brain melting inapplicable — only new matter: water found in skull — we come to declare new treifah: whence innovate treifot not in Chazal? The matter was suppressed and we may not add treifot — simple and clear; Taz is correct: Bahag came to be lenient, not add treifot.`,
  '3#א': `And such, etc. — Shach challenged without the reason we are not expert we should treifah, for certainly upper was perforated; fine challenge per Hagahot Ra'osh; but in truth Mordechai and Tosafot Gittin imply no perforation at all — entered through nostril; if so declaring treifah for upper perforated is because of two wordings in Gemara — we go stringently; double safek: perhaps not perforated; if perforated — perhaps only upper — upper alone kosher for that wording. Therefore forbidden because examination needed and we are not expert; double safek does not help since examination is possible and we are not expert — no double safek — examine. Here truly all lenient reasons relied on Titus the wicked: they challenged — many things done to Titus unnatural; all to his detriment since he denied nature is repaid unnaturally; not to change nature to treifah for him — life more than twelve months we do not say for such an evildoer; "when the wicked perish there is joy." To be stringent we may hear Rabbenu Tam who distinguishes man and animal — Titus no proof for animal treifot; if so both membranes perforated in man should be kosher — how can Gemara on mushy brain treifah? Difficult; must say as Tosafot end Zevachim: we derive treifah invalid for man "with you" similar to you; they challenged: perhaps Noach himself treifah? Tosafot challenged: he lived long after Flood — Rabbenu Tam answered: accustomed to distinguish man's treifah has no mazal, animal has mazal — for practical law. Piskei Tosafot: man's treifah lives more than animal; Titus too treifah through gnat yet lived years — true authors cried: Gemara Chullin brings proof on skull deficiency one family — man's treifah; for skull deficiency in Ohalot dealing with man: "so it may be removed quickly and die" — this treifah is strong: even in man dies immediately — as above; therefore they asked "we see he lived"? Answer: within twelve months. But difficult from agunah: if husband treifah they permit wife to another after twelve months — Yerushalmi: fell in water, feet raised — if from knee up wife permitted — learn treifah does not live even in man. See Beit HaZahav and Peri Chadash. It appears for practical law: certainly Yeshuot Hashem explained "treifah does not live" means majority do not live but minority live; safek treifah we permit — we follow majority; still hard in animal — why does Gemara expound our mishnah and R' Eliezer fetus treifah — why not explain simply some minority treifah? Learn no treifah animal gives birth or lives twelve months — forced to distinguish live twelve months from birth only in animal; man has mazal sometimes lives more — minority; agunah we follow majority treifot even in man not live twelve months; but Nach can explain: perhaps this man's mazal abundant — minority lived more; Titus too time stood — minority lived more. Vain outcry against Tosafot and Piskei Tosafot — examine. Also proof for above siman 50 for Shmuel's view treifah lives — difficult chapter Aleph Tav safek derusah before Shmuel — strangled and threw in river; Gemara challenges: let them remain twelve months? Hard if Shmuel holds treifah lives — per above fine: Shmuel holds in animal not live, in man lives. Understand Tosafot' challenge on Rabbenu Tam: Rabbenuim challenged R' Yehuda: bladder perforated treifah from Iyov "he pours my gall on the ground" — yet Iyov stood — what challenge? There is difference man and animal? Seemingly easy: if weakness reached treifah level — what helps mazal? Mazal does not change impossibility to possibility — only here mazal causes his cure to succeed — mazal's action; ancients divined cure times by stars, herbs — see Rambam chapter place where they buried medical books for Chizkiyahu; therefore in man not treifah: if medicine given and lives — mazal helped cure succeed; unlike animal without mazal — cure does not succeed. From Iyov below he properly challenges: no medicine given — man and animal equal (see Tosafot daf 43 s.v. yafle, Shabbat 53a: amulet helps man not animal — has mazal). No claim against Tosafot on Rabbenu Tam — Tosafot wrote explicitly no cure for Iyov — seemingly difficult. Perhaps resolve: Rabbenuim asked R' Yehuda from "he pours my gall" — how hidden from them "he heals my kidneys"? Must be they knew Satan "keep his soul" — thought keeping was if medicine given lives — not dead man, not treifah; only dangerous to die — Satan kept soul; but treifah dead man — Satan would not keep alive; Iyov said "He may kill me" — not already killed; treifah dead man; "keep his soul" means not make treifah — otherwise what if He kills entirely? They properly challenged Rabbenu Tam from gall — per R' Yehuda treifah; but kidneys though dangerous not treifah — Satan kept well — examine. Nevertheless no difficulty for Rabbenu Tam on Iyov — how say he has mazal helping? His mazal was for evil — stars fought from their courses "let the day perish" — all in truth without exaggeration like poets — examine. See below siman 57 where I lengthy answered in Birchat HaZevach — examine.`,
  '3#ב': `Custom — Beit Yosef wondered why not say "after slaughter"; Shach explained: after, because concern only one membrane perforated — more concern while alive than lung where two membranes required; Darishah and Shach: lung floats constantly — more common after slaughter perforation; also brain membrane very soft; these generally safek whether before or after slaughter; still difficult: why not establish animal in presumption of kashrut and say now after slaughter perforated? What of cheese permitted retroactively for all even Rashba if not forced to say before slaughter — we say now it became impure; here too Rama: if doubt whether worm left yesterday before slaughter or on eve — presume yesterday to permit cheese made retroactively, say today left; though no presumption there, only now became impure; but no presumption of kashrut — animal ends treifah; here presumption now became impure and presumption of kashrut — we say after slaughter — permitted. Therefore clear: if we judge how worm came — through nostril or perforated — certain we say worm found here was there before, etc.; but forced; why not say grew in skull from brain rot and moisture? If pouch grows why not worm? But main case: worm between membrane and membrane without hole — therefore we say if after slaughter would have perforated from blow not visible — therefore before slaughter; healing in membrane from blow impossible after slaughter. But if hole found without blood drop — simple we say after slaughter separated; matter on its presumption — examine.`,
});

// --- pitchei-teshuva (4) ---
patchFile('siman_031/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>Bore-through perforation — treifah.</b> See responsum Beit Ephraim part 4 siman 6: asked regarding a place where a slaughterer opened a large animal's skull, removed the brain, and saw inside the skull emerging inward from the skull bone a single long bone like a barley length prominent beside the brain — found on both sides of the skull; mostly near the horns outside; point sharp; known it presses the brain membrane inward and into the brain itself. Brought before the rabbi — peeled upper brain membrane from skull bone — perforated — declared treifah; afterward in many slaughtered animals this matter was found frequently. Three doubts: (1) require examination initially to open skull and check since minority occurrence? (2) if such points in skull bone — suffice to examine brain membrane whole, or say we are not expert? (3) if examination helps — law if membrane lost or torn before check? He answered first doubt: no initial examination needed even though minority occurrence — a hole in membrane causing treifah is not common; common is finding the defect — unlike lung adhesions commonly treifah. He added reasons: do not be stringent unless no loss at all where treifot sell at profit like kosher. If examined and found this defect — do not be stringent saying we are not expert, since known place aimed at points; even if cannot aim place — do not be stringent; visual examination suffices; upper membrane peel unnecessary. If membrane lost or torn before examination — treifah. See there at length (and see responsum Mishkenot Yaakov siman 15 disputing Beit Ephraim gaon on this matter).`,
  '2#_': `<b>Great loss.</b> See responsum Har HaCarmel Yoreh Deah part siman 15 explaining in several places leniency in hefseid merubeh — how much is hefseid merubeh. He brought Nachalat Shiva siman 55: general — loss more than one-sixth of value is hefseid merubeh (also in Beit HaTov siman 95 s.k. 4 with slight change — see there). He disputes: if item worth six gold and loss more than one gold — permit for owners' hefseid merubeh; but if worth six hundred gold and loss ninety-nine gold — forbid, saying only slight loss — words of rabbanan like mockery. He also refuted Nachalat Shiva's other words. He concluded: no fixed amount — all per teacher's eyes, time, and person whose loss it is — if great to him, hefseid merubeh — see there. See responsum Maor HaGolah Rabbi Akiva Eiger siman 43: doubtful in several matters where they are lenient in hefseid merubeh — such as bubbles adhering in water: if butcher slaughtered two or three animals all with two adhering bubbles — one animal not hefseid merubeh, two or three is — is that hefseid merubeh or not since each alone is not? Discuss to be lenient — see there simanim; from this if three animals of three people — even all came together before rabbi needing ruling treifah — not hefseid merubeh, no leniency; possibly same one animal of partners — not hefseid merubeh to each (see responsum Chasam Sofer Orach Chaim siman 65 brought in Pithei Teshuvah Orach Chaim siman 472 seif 1: permitted in hefseid merubeh only for animal owner and household due to his loss; why should others buy initially? Probably must inform; if sold without informing — possible defect in sale and return; but if no other kosher meat in city except this animal permitted in hefseid merubeh — permitted for all; only scrupulous souls who are stringent on themselves, etc. However from Ra'ak responsum: even butcher selling to others they permit in hefseid merubeh — strained to say dealing when no other meat; then obvious to be lenient for community need; nevertheless certainly must inform as Chasam Sofer; proper in such case to lower price slightly for poor).`,
  '3#_': `<b>And the skull — treifah.</b> See Beit HaTov; seemingly the "in skull" Taz wrote at beginning is not precise — he permits also inside membrane if brain not missing — as end of his words implies; also Shach who wrote "all the more water" disputes Taz — from his words water is stricter than pouch; Taz holds water lighter; Peri Chadash, Turei Zahav, Pri Megadim wrote on this; see Levushei Serad ot 11 explaining Taz and Shach well; also wrote "in skull" not precise; explained Shach does not dispute Taz — "all the more water" means where brain is missing; conclusion for law: both Taz and Shach — plain water if brain not missing — kosher even inside membrane, all the more on membrane between membrane and skull; if missing — inside membrane kosher where brain surrounds; but on membrane treifah even if brain surrounds — deficiency — water certainly from missing brain exposed to membrane; same plain water; but pouch inside or on membrane — treifah even if brain whole (so appears to rule — see there).`,
  '4#_': `<b>[Covered or not — treifah.</b> See responsum Kehillat Yaakov siman 3 lengthy on this; concludes to be lenient in this safek since Rif, Rambam, Ra'avad are lenient on essence of this disqualification of water in head — they hold not treifah even exposed to membrane except entirely or majority; if so when further safek perhaps not exposed — per many poskim permit due to presumption slaughtered-permitted; though we do not rely on it alone — with double safek certainly combine this safek of authorities leaning to permit in every manner — permit this safek more than other treifah safek which is only one safek — so he acted. It appears where sides exist anyway to be lenient such as mixtures — combine this.]`,
});

// --- rabbi-akiva-eiger-yd (4) ---
patchFile('siman_031/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(siman 31 seif 1 in gloss) <b>And such is the custom unless in a place of hefseid merubeh.</b> Meaning: perforated through illness where we see it did not control the lower; but through a thorn — even in animal one may say treifah even in hefseid merubeh, lest lower was perforated — see Shach s.k. 5; and in Pri Megadim there.`,
  '2#_': `(Shach s.k. 3) <b>As below siman 32.</b> We are not expert in this measure; therefore whenever brain crushed somewhat we are concerned perhaps that is its measure — Bach. And this is when exposed a little to membrane; but brain surrounding on all sides — kosher; if safek whether brain surrounds — seemingly one should judge double safek: perhaps did not reach melting measure; if reached — perhaps covered by brain; and even safek whether reached melting is safek of missing knowledge — nevertheless be lenient in hefseid merubeh as Rama ruled siman 110.`,
  '3#_': `(Taz s.k. 3) <b>It is simple one must forbid; and if while alive afterward shook its head — twelve months one may say permitted without examination.</b> And if after slaughter found brain does not surround water — if it did not remain twelve months — milk certainly forbidden from shaking onward; if remained twelve months — milk before twelve months appears permitted, afterward — uncertain.`,
  '4#_': `(seif 3) <b>Such as in the nostril — kosher.</b> And this is when no trace and no blood drop there — as Nahalat Shiva.`,
});

// --- mateh-yehonatan (2) ---
patchFile('siman_031/mateh-yehonatan/part-001.txt', 'mateh-yehonatan', {
  '1#_': `(siman 31 seif 1 in Hagahot) <b>And such is the custom, etc.</b> See Shach s.k. 5; it appears from his words he explains Mechaber: worm found between two membranes — in truth so in Hagahot Ashiri in the name of R' Chananel; but Mechaber may be explained as Mordechai: worm found inside brain itself — came from outside; so from Tosafot Gittin daf 56 — see there; therefore Rama wrote: if we were expert in examination it would be permitted; and what Shach wrote not comparable to worms on lung, etc. — one may say: certainly if hole also in brain — say after slaughter separated; here we deal only with blood drop — certainly before slaughter separated, for after slaughter no blood drop is made at all; but truth of matter: most poskim do not say "after slaughter separated" except regarding lung, not elsewhere.`,
  '2#_': `(there seif 2 in gloss) <b>There was a doubt whether covered by brain or not — treifah.</b> See Tosafot chapter Aleph Tav daf 42b s.v. k'savar ein choshshin, etc.: we establish on presumption from life, etc. — see there; if so here we should establish on presumption brain presumably surrounded water; it appears every animal with water in brain — more common water surrounds; it is like safek derusah where we do not establish on initial presumption.`,
});

// --- kaf-hachayim (4) ---
patchFile('siman_031/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>A) [seif 1] The brain has two membranes, etc.</b> Upper membrane attached to skull inside; lower membrane is soft membrane in which brain rests — Rashi Chullin 45a; so Nahalat Shiva in Hagahot Tosefta ot 1, Zevachim Tosefta ot 1, Chokhmat Adam general 15 ot 6.`,
  '2#_': `<b>B) there. The brain has two membranes one upon the other; lower perforated bore-through — treifah.</b> Lower membrane adheres to brain and is soft; if perforated until reaching brain — treifah, for this is its bore-through perforation since it has no cavity; as Ran beginning chapter 3 Chullin: every organ disqualified by perforation with a cavity — not disqualified until perforated into cavity; if no cavity such as brain membrane — bore-through required — see there; if perforation reached brain — called bore-through — treifah — Zevachim Tosefta ot 4.`,
  '3#_': `<b>C) there. But if upper alone perforated — kosher. Gloss: and some declare treifah, etc.; and such is custom unless hefseid merubeh.</b> Maharshal chapter Aleph Tav siman 11 and Bach forbid even in hefseid merubeh — see there; Taz s.k. 1; Shach s.k. 1; but Peri Chadash ot 1 wrote main thing lenient per gloss in hefseid merubeh; so Turei Zahav ot 1, Zikhron Adam part 3, brief 5 treifot ot 5 from Mechaber ot 3, Zevachim Tosefta ot 4, Chokhmat Adam there, Beit Yitzchak ot 1, Kometz ot 1, Einei HaKohen siman 3 ot 1, Zevach Todah ot 1.`,
  '4#_': `<b>D) However</b> this is ordinary perforation; but if entire upper skin or majority impaired — even if lower has no defect — declare treifah even in hefseid merubeh — Turei Zahav end ot 1 from Shulchan Aruch ot 1, Beit Yitzchak there, Kometz there, Einei HaKohen there, Zevach Todah ot 3.`,
});

// --- yad-avraham (2) ---
patchFile('siman_031/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(siman 31 seif 1) <b>The brain has two membranes one upon the other; lower perforated, etc. — treifah.</b> So is Rif's view; and it appears to Ran so is Rambam chapter 6 Hilchot Shechitah. Tur wrote in Rambam's name: not treifah until both perforated — Ra'avan's view. Beit Yosef is truly doubtful of Rambam's view; hidden from him what Rambam wrote in mishnah commentary chapter Aleph Tav explicitly as Ran per his view — from there we learn explanation of his composition; if lower perforated — treifah — meaning lower alone too. So in books, Turei Zahav, and Arukh. This is majority poskim: Rambam, Rif, Ran, Hagahot Ashiri, Mordechai, R' Chananel, Rashba, R' Ovadiah of Bartenura in mishnah commentary, Ra'ah in Bedek HaBayit. So explicit in Talmud; Rif, Ra'osh, Rashba, Tur in this matter until bulbs: membrane perforation in any amount; from there onward majority. So explicit Rambam chapter 6 Hilchot Shechitah; Beit Yosef brings siman 32 regarding spinal cord beginning from bulbs outward — majority; above that — any amount — see there — examine. One may wonder on Tur appearing not treifah in lower alone until both perforated; if so how wrote in this matter what R' Yehuda ben Levi said in Talmud (daf 45) until bulbs; and explicitly Ra'osh R' Yehuda ben Levi holds lower alone treifah. Resolve: practical difference if lower perforated there — treifah; if upper also perforated — if upper alone also not treifah — examine.`,
  '2#_': `(there seif 3) <b>If worm found in brain membrane, etc.; and no trace or blood drop in lower membrane — kosher.</b> Mordechai and Maharshal brought proof from Titus — gnat entered his brain yet lived seven years. Per Tosafot chapter HaNizakin (daf 56) distinction treifot man and animal — no proof from there. Also no proof from Titus — miracle that God gave strength to receive judgment for fighting God — as we say chapter Aleph Tav (daf 43) regarding Iyov: tested differently — examine. In truth in my humble opinion proof from Talmud, Rashi, Ran end chapter Aleph Tav (daf 67) kukani — prisoners — Rashi: worms in liver and lung; see Rambam chapter 2 Hilchot Ma'achalot Assurot: worms in brain in animal head — 49 kinds enter through nostril — Rashi: when animal sleeps they enter nostril to lung and liver — end; implies animal permitted like worms in liver siman 41 and Morana in lung siman 36 seif 5; worms certainly in skull when entering nostril — all the more Rambam found there; learn: kosher even if found in skull since entered nostril and did not perforate membrane — as Tosafot chapter HaNizakin s.v. veniker mochai. Do not challenge: per gloss to forbid worm in skull — how permit Morana in lung — was like Morana in skull since certainly there? Say: per Talmud conclusion chapter Aleph Tav — double safek: perhaps from outside, never reached brain; still forbidden as eiver min hachai as Tur siman 84 s.t. 16; if from outside — perhaps membrane not perforated — like worm in nostril kosher even if mouth outward — such double safek. Uncertain: per Taz here first answer — require membrane examination even if in nostril — require examination also Morana in lung and worms in liver — no posek said so; indeed not proper to be stringent on nostril worm where double safek — no need to clarify as Darkei Moshe siman 53 and gloss siman 110 seif 10; even per gloss siman 53 seif 4 to be stringent safek missing knowledge we are not expert — nevertheless main answer second of Taz: here like found in esophagus or belly siman 33 and 48 — we need not say it made a hole; unlike where one may say perforated — perhaps perforated further; see siman 36 s.k. 5 this reasoning in Ra'ah Bedek HaBayit. Know: I saw Rav Toviah in mishnah commentary these bird treifot wondrous — wrote bird treifah through upper membrane alone even per view in animal lower membrane; very wondrous — proven explicit Talmud, Rashi chapter Aleph Tav (daf 56), Ra'osh chapter Aleph Tav siman 11, Rashba Tur HaDeshen long (daf 30): per view in animal upper alone not treifah — same in bird; Levi taught general: all treifot listed for animal — corresponding in bird — needs study.`,
});

// --- yad-ephraim (2) ---
patchFile('siman_031/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>Unless in a place of great loss.</b> See Beit HaTov; see Peninei Me'ir siman 54 resolving Beit Yosef's difficulty on R' Yonah who wrote there in Rabbenu Tam's name: skull deficiency with upper membrane — his words wondrous, for in understanding Hagahot R' Yehuda he is Rabbenu Tam — Hagahot Gedolot writes what Bahag concluded is Hagahot Gedolot; writes to be stringent like Rabbenu Tam — very wondrous, for Bahag preceded Rif and Rashi by generations, all the more Rabbenu Tam; but Hagahot R' Yehuda — though final hei missing one must mark at end; so found several times; Mahari Beruna already noted — see there. See responsa Beit Ephraim: in one city slaughterer opened large animal skull, removed brain, saw inside skull from skull bone inward a single long bone, sometimes barley length, prominent beside brain, sharp point, slightly wide at bottom half-finger, narrow above — found many times. I ruled no examination required afterward unless no loss at all where treifot sell like kosher; unlike when loss in treifot — examination afterward prevents slaughter and we fear loss and community pressure. If examined and found defect — do not be stringent saying not expert; visual and tactile examination fine since known place aimed at points; even if cannot aim exact place in lower — may rely on lower examination and good viewing; upper peel unnecessary after ruling spread upper alone kosher in hefseid merubeh — may rely at least not to require upper examination; but if through lower examination hole found — treifah; even if brain membrane lost before examination — treifah from safek it fills whole cavity — concern long bone reached lower and perforated; though some side to leniency — do not act to be lenient.`,
  '2#_': `<b>And if not — treifah.</b> See Beit HaTov; see Eshel Avraham: Radbaz like Taz — incorrect, Radbaz not dealing with this as Peri Chadash explains if safek water exposed; Peri Chadash disputes and is stringent. Mahari Beruna: proper to fear not to act. Nekudot HaKesef siman 32: half lamb salted with two more sheep; remaining half sent elsewhere with head — water found; those salted here — meat mixed; also salted with geese; rabbi wanted to combine voices safek treifah water in head — brain perhaps surrounded, not clear; since all poskim treifah, Rama, Shach, Maharam Lublin, Peri Chadash, Turei Shoshanim — all forbid; anyway none permits God forbid to be lenient, etc. Also told me: not like making rabbinic safek since when safek known elsewhere was separate without mixture; also in salting hard to say half treifah touched only birds. For law: meat, birds, vessels cooked in them forbidden — see there; implies even hefseid merubeh; Yom Tov was stringent; Taz's law if brain whole and water in skull — Mahari Beruna brought many latter authorities like Taz not like Peri Chadash; so they acted — see Beit Yehudah daf 114 and responsa Pri HaAdamah part 3 daf 43.`,
});

console.log('Siman 031 patch complete.');
